---Q1:retrieves the first 5 rows and all columns from your customer table.---
select * from customer limit 5;


---Q2: What is the total revenue generated by male vs female customers?---


select gender, sum ("purchase amount (usd)") as revenue
from customer
group by gender;


---Q3: Which season generates the highest total revenue?---
select season,
	sum ("purchase amount (usd)") as total_revenue
	from customer
	group by season
	order by total_revenue DESC;
	

---Q4: Which product category has the highest average customer review rating?
select category,
round(avg("review rating":: numeric),2) as avg_rating
from customer
group by category
order by avg_rating DESC;


---Q5: What are the top 5 locations with the highest number of orders?---
select location,
count("customer id") as total_orders
from customer
group by location
order by total_orders DESC
limit 5;


---Q6: Which payment method is most preferred by customers?---
select "payment method",
      count("customer id") as usage_count,
       sum("purchase amount (usd)") as total_spent
from customer
group by "payment method"
order by usage_count DESC;


---Q7: Which top 5 clothing sizes generate the most revenue?---
select size,
count("customer id") as items_sold,
sum("purchase amount (usd)") as total_revenue
from customer
group by size
order by total_revenue DESC;


---Q8: How does shopping frequency affect average spending?---
select "frequency of purchases",
	count("customer id") as customer_count,
	round(avg("purchase amount (usd)"),2) as avg_spend
from customer
group by "frequency of purchases"
order by avg_spend DESC;

---Are customers who are repeat buyers (more than 5 previous purchases) also likely to subscribe?---
select  "subscription status",
       count ("customer id") as repeat_buyers
from customer
where "previous purchases" > 5
group by "subscription status";